[{"order":1,"type":"heading","text":"Partitioning in PostgreSQL: Declarative Range, List, and Hash"},{"order":2,"type":"paragraph","text":"PostgreSQL declarative partitioning allows you to split a logically large table into smaller, more manageable physical pieces called partitions. This guide explores the three main types of declarative partitioning: Range, List, and Hash."},{"order":3,"type":"subheading","text":"1. Declarative Range Partitioning"},{"order":4,"type":"paragraph","text":"Range partitioning divides the table into partitions defined by a range of values of a specific column or expression, with no overlap between the ranges. It is commonly used for time-series data."},{"order":5,"type":"code","text":"CREATE TABLE measurements (
    log_id bigint,
    log_date date NOT NULL,
    sensor_data text
) PARTITION BY RANGE (log_date);"},{"order":6,"type":"paragraph","text":"Next, create individual partitions for specific date ranges:"},{"order":7,"type":"code","text":"CREATE TABLE measurements_y2023m01 PARTITION OF measurements
    FOR VALUES FROM ('2023-01-01') TO ('2023-02-01');

CREATE TABLE measurements_y2023m02 PARTITION OF measurements
    FOR VALUES FROM ('2023-02-01') TO ('2023-03-01');"},{"order":8,"type":"subheading","text":"2. Declarative List Partitioning"},{"order":9,"type":"paragraph","text":"List partitioning is used when you want to partition a table by explicitly listing which key values appear in each partition. This is ideal for categorical data like regions or status codes."},{"order":10,"type":"code","text":"CREATE TABLE customers (
    customer_id int,
    name text,
    country text
) PARTITION BY LIST (country);"},{"order":11,"type":"paragraph","text":"Now, create partitions for specific country codes:"},{"order":12,"type":"code","text":"CREATE TABLE customers_usa PARTITION OF customers
    FOR VALUES IN ('USA', 'US');

CREATE TABLE customers_eur PARTITION OF customers
    FOR VALUES IN ('DE', 'FR', 'UK');"},{"order":13,"type":"subheading","text":"3. Declarative Hash Partitioning"},{"order":14,"type":"paragraph","text":"Hash partitioning partitions data by specifying a modulus and a remainder. PostgreSQL automatically applies an internal hash function to evenly distribute rows across partitions."},{"order":15,"type":"code","text":"CREATE TABLE accounts (
    account_id int,
    account_name text
) PARTITION BY HASH (account_id);"},{"order":16,"type":"paragraph","text":"Create partitions specifying the modulus and remainder:"},{"order":17,"type":"code","text":"CREATE TABLE accounts_p1 PARTITION OF accounts
    FOR VALUES WITH (MODULUS 3, REMAINDER 0);

CREATE TABLE accounts_p2 PARTITION OF accounts
    FOR VALUES WITH (MODULUS 3, REMAINDER 1);

CREATE TABLE accounts_p3 PARTITION OF accounts
    FOR VALUES WITH (MODULUS 3, REMAINDER 2);"},{"order":18,"type":"subheading","text":"Best Practices"},{"order":19,"type":"bullet_point","text":"Always include the partition key in the primary key or unique constraints of the partitioned table if constraints are required."},{"order":20,"type":"bullet_point","text":"Monitor query execution plans to ensure partition pruning is active (PostgreSQL skips scanning irrelevant partitions)."},{"order":21,"type":"bullet_point","text":"Regularly drop or detach old partitions rather than running massive DELETE statements to maintain optimal performance."}]
